 * Plain data, because redaction works by key: flattening `{ token: "sk-..." }` to text first would hide the
 * key from `redact()` and only a secret-SHAPED value would still be caught. Bounded and inert, because the
 * value comes from arbitrary code -- a surviving `toJSON` would run after redaction and write back what
 * redaction had just removed, and a cycle, a getter that throws, or an unserialisable value would take the
 * whole line down. Errors keep their name and message; anything unreadable degrades to a marker.
 */
export function describeThrown(value: unknown, depth = 0, seen: WeakSet<object> = new WeakSet()): unknown {
  switch (typeof value) {
    case "bigint":
      return `${value}n`;
    case "symbol":
      return value.toString();
    case "function":
      return `[function ${value.name || "anonymous"}]`;
    case "object":
      break;
    default:
      return value; // string, number, boolean, undefined -- AppLogger redacts strings itself
  }
  if (value === null) return null;
  if (value instanceof Error) return `${value.name}: ${value.message}`;
  if (seen.has(value)) return "[circular]";
  if (depth >= MAX_DEPTH) return "[truncated]";

  seen.add(value);
  try {
    if (value instanceof Map) {
      return fromEntries([...value].map(([k, v]) => [String(k), v] as const), depth, seen);
    }
    if (value instanceof Set) return [...value].slice(0, MAX_ENTRIES).map((v) => describeThrown(v, depth + 1, seen));
    if (Array.isArray(value)) return value.slice(0, MAX_ENTRIES).map((v) => describeThrown(v, depth + 1, seen));
    return fromEntries(readOwnEntries(value), depth, seen);
  } catch {
    return "[unreadable]";
  } finally {
    seen.delete(value); // only an ancestor is a cycle; the same object twice in one line is not
  }
}

/** Own enumerable properties, read one at a time: a getter that throws costs its own key, not the line. */
function readOwnEntries(value: object): (readonly [string, unknown])[] {
  return Object.keys(value)
    .slice(0, MAX_ENTRIES)
    .map((key) => {
      try {
        return [key, (value as Record<string, unknown>)[key]] as const;
      } catch {
        return [key, "[unreadable]"] as const;
      }
    });
}

function fromEntries(entries: (readonly [string, unknown])[], depth: number, seen: WeakSet<object>): Record<string, unknown> {
  const out: Record<string, unknown> = {};
  for (const [key, value] of entries.slice(0, MAX_ENTRIES)) out[key] = describeThrown(value, depth + 1, seen);
  return out;
}

