  // object cannot be re-expanded down every route to it. Without this a handful of objects referencing each
  // other amplify to MAX_ENTRIES ^ MAX_DEPTH entries -- hundreds of megabytes on one line.
  if (seen.has(value)) return "[seen]";
  if (depth >= MAX_DEPTH) return "[truncated]";

  seen.add(value);
